CREATE DATABASE IF NOT EXISTS communityhub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE communityhub;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,discord_id VARCHAR(32) UNIQUE,discord_username VARCHAR(100),username VARCHAR(100) NOT NULL,display_name VARCHAR(100),avatar_url TEXT,bio VARCHAR(1000) NOT NULL DEFAULT '',email VARCHAR(255) UNIQUE,password_hash VARCHAR(255),email_verified BOOLEAN NOT NULL DEFAULT FALSE,role ENUM('applicant','reviewer','department_command','staff','admin','management','owner') NOT NULL DEFAULT 'applicant',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE email_verification_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE departments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,description TEXT,discord_role_id VARCHAR(32),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE application_forms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL,description TEXT,is_open BOOLEAN DEFAULT TRUE,min_age INT NULL,cooldown_days INT DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE application_questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,form_id BIGINT UNSIGNED NOT NULL,label VARCHAR(255) NOT NULL,help_text TEXT,question_type ENUM('text','textarea','number','select','checkbox','date','url') DEFAULT 'text',options_json JSON NULL,is_required BOOLEAN DEFAULT FALSE,sort_order INT DEFAULT 0,FOREIGN KEY(form_id) REFERENCES application_forms(id) ON DELETE CASCADE);
CREATE TABLE applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,form_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,status ENUM('draft','submitted','under_review','changes_requested','interview','accepted','denied','withdrawn','archived') DEFAULT 'submitted',submitted_at DATETIME NULL,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,decision_reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(form_id) REFERENCES application_forms(id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE application_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,answer_text LONGTEXT,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES application_questions(id) ON DELETE CASCADE);
CREATE TABLE application_status_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL,note TEXT,changed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE application_notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,author_id BIGINT UNSIGNED NULL,note TEXT NOT NULL,is_private BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reporter_user_id BIGINT UNSIGNED NULL,report_type VARCHAR(80) NOT NULL,reported_name VARCHAR(150),reported_discord_id VARCHAR(32),occurred_at DATETIME NULL,description LONGTEXT NOT NULL,evidence_url TEXT,status ENUM('open','under_review','actioned','dismissed','closed') DEFAULT 'open',assigned_to BIGINT UNSIGNED NULL,resolution TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(reporter_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE report_comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,report_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,comment TEXT NOT NULL,is_internal BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE calendar_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,event_type ENUM('training','interview','patrol','meeting','community','other') DEFAULT 'community',description TEXT,location VARCHAR(255),start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,max_attendees INT NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(start_at));
CREATE TABLE event_attendees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status ENUM('going','maybe','declined','attended','no_show') DEFAULT 'going',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(event_id,user_id),FOREIGN KEY(event_id) REFERENCES calendar_events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE document_folders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,department_id BIGINT UNSIGNED NULL,is_private BOOLEAN DEFAULT TRUE,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES document_folders(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,folder_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL UNIQUE,mime_type VARCHAR(150),file_size BIGINT UNSIGNED DEFAULT 0,uploaded_by BIGINT UNSIGNED NULL,version INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(folder_id) REFERENCES document_folders(id) ON DELETE SET NULL,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE interviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,interviewer_id BIGINT UNSIGNED NULL,start_at DATETIME NOT NULL,end_at DATETIME NULL,location VARCHAR(255),status ENUM('scheduled','completed','cancelled','no_show') DEFAULT 'scheduled',notes TEXT,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE,FOREIGN KEY(interviewer_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED NULL,metadata_json JSON NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE site_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value LONGTEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
